gatZ(){return"\xdaltimo erro:"},
gaou(){return"Copiar erro"},
gaqt(){return"Erro copiado para a \xe1rea de transfer\xeancia"},
gIk(){return"Categorias"},
ga8i(){return"Buscar categoria..."},
aut(a,b){return"Or\xe7amento "+a+": "+b},
apq(a){return"Or\xe7amento padr\xe3o: "+a},
