gamk(){return"Valor deve ser maior que zero"},
gapd(){return"Informe um dia entre 1 e 31"},
gapo(){return"Valor padr\xe3o"},
gapb(){return"Dia do m\xeas (1\u201331)"},
ap8(a,b){return"Dia "+a+" \xb7 "+b},
gasG(){return"Inativa"},
gapf(){return"Desativar"},
ape(a){return"Erro ao desativar: "+a},
gawL(){return"Reativar"},
awK(a){return"Erro ao reativar: "+a},
gav2(){return"Nenhum cart\xe3o cadastrado"},
gaxJ(){return"Clique + para adicionar"},
gax5(){return"Remover Cart\xe3o"},
ax4(a){return'Remover "'+a+'"? Os gastos associados n\xe3o ser\xe3o exclu\xeddos.'},
ganI(){return"Informe um nome para o cart\xe3o"},
gaqb(){return"Editar Cart\xe3o"},
